/** UmsRcvrContactBackfillMapper.updateOne */
UPDATE cdm_own.cmpt_ums_rcvr
   SET mbr_telno         = #{telno}
      ,mbr_telno_bidx    = #{telnoBidx}
      ,mbr_eml_addr      = #{email}
      ,mbr_eml_addr_bidx = #{emailBidx}
 WHERE ums_id = #{umsId}
   AND ums_sn = #{umsSn}

/** UmsRcvrContactBackfillMapper.updateUserOne */
UPDATE cdm_own.usr
   SET mbl_tel_no  = #{mblTelNo}
      ,home_tel_no = #{homeTelNo}
      ,eml_addr    = #{emlAddr}
 WHERE usr_id = #{userId}

/** UmsRcvrContactBackfillMapper.updateCmpyOne */
UPDATE cdm_own.cmpt_cmpy_inf
   SET cntct_phone = #{cntctPhone}
      ,cntct_email = #{cntctEmail}
 WHERE cmpy_id = #{cmpyId}
